const punishmentLabels: Record<string, string> = {
  vw: 'Verbal warning', strike_1: 'Strike I', strike_2: 'Strike II',
  disciplinary_1: 'Disciplinary I', disciplinary_2: 'Disciplinary II',
  blacklist: 'Blacklist', exile: 'Exile', suspension_3: 'Suspension · 3d',
  suspension_7: 'Suspension · 7d', suspension_14: 'Suspension · 14d',
};
